1	package posemap
2	
3	import (
4		"math"
5		"sort"
6	)
7	
8	// poseShift 描述一次回环校正对轨迹施加的同一次刚体重定位：锚点落到目标
9	// 位置、朝向归一到 [-π,π)；从锚点到末帧的其余帧与锚点一起平移旋转，保留
10	// 各帧相对锚点的位置关系与朝向差。提交校正（Correct）与打开地图时的校正
11	// 记录几何核对（validateLoaded，见 persistence.go）共用这同一份规则与
12	// 运算次序，两处对“校正后位置与朝向”的理解因此始终一致。
13	type poseShift struct {
14		x, y          float64 // 目标位置，即锚点校正后位置
15		heading       float64 // 目标朝向归一到 [-π,π)，即锚点校正后朝向
16		anchorX       float64 // 锚点校正前位置
17		anchorY       float64
18		anchorHeading float64 // 锚点校正前朝向
19		dHeading      float64 // 归一后的最短朝向差，即各帧叠加的旋转角
20		cosD, sinD    float64 // 旋转角的余弦与正弦
21		tx, ty        float64 // 纯平移校正（旋转角为 0）时各轴的平移量
22		identity      bool    // 只调方差的恒等校正：位置与朝向保持原值
23	}
24	
25	// newPoseShift 按提交目标与锚点校正前位姿构造重定位。目标朝向先归一，
26	// 旋转角取归一后的最短朝向差。目标位置与锚点原位置完全相同、目标朝向归
27	// 一后与原朝向等价（旋转角为 0）时是恒等校正：几何上没有任何平移或旋
28	// 转，校正前后位姿必须完全相同。恒等校正不能套用旋转平移公式——公式会
29	// 先求相对锚点的偏移，轨迹横跨 ±1e308 这类大坐标时该差值先溢出为
30	// ±Inf、再参与浮点运算退化为 NaN，使本应成功的校正被误判为数值异常；
31	// 恒等校正直接保留原位姿。纯平移校正（旋转角为 0 但位置有移动）同理不
32	// 能套用该公式：它按“各轴平移量 = 目标轴坐标 − 锚点原轴坐标”逐轴平移，
33	// 只要各轴平移量与校正后坐标有限，轨迹横跨多大坐标都不会凭空溢出。
34	func newPoseShift(tgt CorrectionTarget, anchorBefore Pose) poseShift {
35		heading := normalizeAngle(tgt.Heading)
36		dHeading := normalizeAngle(heading - anchorBefore.Heading)
37		return poseShift{
38			x:             tgt.X,
39			y:             tgt.Y,
40			heading:       heading,
41			anchorX:       anchorBefore.X,
42			anchorY:       anchorBefore.Y,
43			anchorHeading: anchorBefore.Heading,
44			dHeading:      dHeading,
45			cosD:          math.Cos(dHeading),
46			sinD:          math.Sin(dHeading),
47			tx:            tgt.X - anchorBefore.X,
48			ty:            tgt.Y - anchorBefore.Y,
49			identity:      dHeading == 0 && tgt.X == anchorBefore.X && tgt.Y == anchorBefore.Y,
50		}
51	}
52	
53	// apply 计算一帧校正后的位置与朝向：恒等校正原样保留校正前值；纯平移校
54	// 正（旋转角为 0）按各轴平移量逐轴平移；其余情形把校正前相对锚点的偏移
55	// 随锚点一起旋转平移，朝向叠加同一旋转角并归一到 [-π,π)。帧时间与方差
56	// 不属于几何规则，由调用方处理。
57	//
58	// 纯平移不套用“先求相对锚点偏移再加回目标位置”的通用公式：锚点与某帧
59	// 分处很大的正、负坐标时（如 ±1e308），该偏移先溢出为 ±Inf，即使两轴
60	// 平移量与校正后坐标都有限也会被误判为数值异常。逐轴平移时，某轴平移量
61	// 为零则该轴坐标原样保留（连 -0 也不会被写成 +0），另一轴的平移不影响
62	// 它；某轴平移量本身溢出为无穷时，校正后坐标随之非有限，仍由调用方按既
63	// 有数值异常规则整次拒绝。
64	//
65	// 朝向按“目标朝向 + 该校正前相对锚点的朝向差”计算，而不是“校正前朝向 +
66	// 旋转角”：二者在数学上（模 2π）等价，但后者先把目标朝向与锚点朝向相减
67	// 再加回，当目标朝向远小于锚点朝向时（例如锚点朝向 1 弧度、目标朝向
68	// 1e-20 弧度），目标朝向会在相减时被锚点朝向的精度吞掉，校正结果退化为
69	// 零——有限且可表示的非零目标朝向必须作为实际定位结果保留。按相对朝向差
70	// 计算时，锚点及原本与锚点朝向完全相同的帧恰好得到目标朝向本身，存在其
71	// 他朝向差的帧仍保留与锚点的相对方向。
72	func (s poseShift) apply(before Pose) (x, y, heading float64) {
73		if s.identity {
74			return before.X, before.Y, before.Heading
75		}
76		if s.dHeading == 0 {
77			// 纯平移：逐轴平移，不经过相对锚点的偏移（见大段注释）。与锚点
78			// 原轴坐标相同的帧（含锚点自身）直接取目标轴坐标：锚点必须准确
79			// 采用提交目标，且校正前同轴坐标相同的帧校正后也必须相同，不能
80			// 因“先减后加”的末位舍入彼此偏离。
81			x, y = before.X, before.Y
82			if before.X == s.anchorX {
83				x = s.x
84			} else if s.tx != 0 {
85				x = before.X + s.tx
86			}
87			if before.Y == s.anchorY {
88				y = s.y
89			} else if s.ty != 0 {
90				y = before.Y + s.ty
91			}
92			return x, y, normalizeAngle(s.heading + (before.Heading - s.anchorHeading))
93		}
94		dx := before.X - s.anchorX
95		dy := before.Y - s.anchorY
96		return s.x + s.cosD*dx - s.sinD*dy,
97			s.y + s.sinD*dx + s.cosD*dy,
98			normalizeAngle(s.heading + (before.Heading - s.anchorHeading))
99	}
100	
101	// Correct 提交一次已确认回环校正。
102	//
103	// req.ID 必须非空；req.Anchor 必须准确命中一个已导入帧的时间（不能是
104	// 初始位姿，也不借用历史查询得到的最近一帧）；目标位姿数值必须有限、
105	// 目标方差必须非负。命中后，锚点帧采用提交的位姿；从锚点到提交时末帧
106	// 的轨迹整体平移并旋转（保持这些帧在校正前彼此的相对位置与朝向，时间
107	// 不变，朝向归一到既有范围）；锚点之后每帧的方差等于目标方差加上锚点
108	// 之后至该帧的原运动方差累计值。更早的位姿不变。
109	//
110	// 受影响帧中的路标观测随新位姿改变地图位置；更早观测的地图位置不变。
111	// 同一路标仍按全部已接受观测、依原时间与同帧输入次序做增量平均并遵守
112	// 合并距离限制；观测次数不变。若校正后出现路标冲突，整次校正拒绝并说
113	// 明冲突帧时间与路标。输入或校正结果含非有限数值同样拒绝；观测转换到
114	// 地图坐标后溢出为 NaN/无穷时按数值异常拒绝，说明该观测所在帧的实际
115	// 时间、路标标识与出现编号，而不是误报为距离冲突。
116	//
117	// 同一标识以相同内容重复提交返回首次结果且不再修改数据；同一标识不同
118	// 内容明确拒绝。任何拒绝或保存失败都不改变轨迹、路标与既有校正记录。
119	// 旧文件缺少逐帧观测来源时，覆盖其历史范围的校正返回 RejectNoBasis。
120	func (m *Map) Correct(req Correction) (CorrectionRecord, error) {
121		m.mu.Lock()
122		defer m.mu.Unlock()
123		if m.closed {
124			return CorrectionRecord{}, ErrClosed
125		}
126		st := m.state
127	
128		// 已保存校正：相同内容直接返回首次记录；不同内容明确拒绝。
129		// 不做任何校验或状态变更，即使其后又提交过其他校正。
130		if hash, ok := st.corrIndex[req.ID]; ok {
131			if hash == canonicalCorrectionHash(req.Anchor, req.Target) {
132				return cloneRecord(st.correctionRecordByID(req.ID)), nil
133			}
134			return CorrectionRecord{}, &RejectError{Kind: RejectCorrectionMismatch, Landmark: req.ID, HasLandmark: true}
135		}
136	
137		if req.ID == "" {
138			return CorrectionRecord{}, &RejectError{Kind: RejectEmptyID}
139		}
140		tgt := req.Target
141		if !isFinite(tgt.X) || !isFinite(tgt.Y) || !isFinite(tgt.Heading) || !isFinite(tgt.Variance) {
142			return CorrectionRecord{}, &RejectError{Kind: RejectNonFinite, Time: req.Anchor, HasTime: true}
143		}
144		if tgt.Variance < 0 {
145			return CorrectionRecord{}, &RejectError{Kind: RejectNegativeVariance, Time: req.Anchor, HasTime: true}
146		}
147	
148		// 锚点必须准确命中已导入帧：trajectory[0] 是初始位姿，不能校正。
149		anchorIdx := -1
150		for j := 1; j < len(st.trajectory); j++ {
151			if st.trajectory[j].Time == req.Anchor {
152				anchorIdx = j
153				break
154			}
155		}
156		if anchorIdx < 0 {
157			return CorrectionRecord{}, &RejectError{Kind: RejectAnchorNotFound, Time: req.Anchor, HasTime: true}
158		}
159		end := len(st.trajectory) - 1
160	
161		// 受影响范围内每一帧都必须有逐帧依据（旧文件没有，不能靠推测校正）。
162		for k := anchorIdx - 1; k < len(st.sources); k++ {
163			if st.sources[k] == nil {
164				return CorrectionRecord{}, &RejectError{Kind: RejectNoBasis, Time: req.Anchor, HasTime: true}
165			}
166		}
167	
168		oldAnchor := st.trajectory[anchorIdx]
169		// 锚点到末帧的整体平移旋转规则（含只调方差的恒等情形）与打开地图时
170		// 的记录几何核对共享同一实现，见上方 poseShift。
171		shift := newPoseShift(tgt, oldAnchor)
172	
173		// ---- 在副本上推演新位姿，真实状态此时保持不变 ----
174		next := append([]Pose(nil), st.trajectory...)
175		accumVar := tgt.Variance
176		for j := anchorIdx; j <= end; j++ {
177			old := st.trajectory[j]
178			if j > anchorIdx {
179				accumVar += st.sources[j-1].moveVariance
180			}
181			x, y, heading := shift.apply(old)
182			np := Pose{
183				Time:     old.Time,
184				X:        x,
185				Y:        y,
186				Heading:  heading,
187				Variance: accumVar,
188			}
189			if !isFinite(np.X) || !isFinite(np.Y) || !isFinite(np.Heading) || !isFinite(np.Variance) {
190				return CorrectionRecord{}, &RejectError{Kind: RejectNonFinite, Time: req.Anchor, HasTime: true}
191			}
192			next[j] = np
193		}
194	
195		// 重放器：观测按帧时间归入当时那次出现、旧观测固定贡献作为起点、
196		// 逐条重建位置的规则与打开地图时的核对共享同一实现（见 replay.go）。
197		replay := newObservationReplay(st.config.MergeDistance)
198		for id, lm := range st.landmarks {
199			replay.track(id, lm.occurrenceWindows())
200		}
201		// 重放帧序列：受影响帧（锚点至末帧）用校正后位姿，更早帧用原位姿；
202		// 旧文件帧没有逐帧依据，其观测已计入对应出现的固定旧贡献，这里按
203		// 空观测帧处理。
204		frames := make([]replayFrame, 0, end)
205		for j := 1; j <= end; j++ {
206			var obs []Observation
207			if src := st.sources[j-1]; src != nil {
208				obs = src.observations
209			}
210			frames = append(frames, replayFrame{time: st.trajectory[j].Time, pose: next[j], observations: obs})
211		}
212	
213		// 受影响的路标出现：在受影响帧中被观测到的全部（标识，出现编号）。
214		// 回环校正跨越同一路标的多次出现时，各次出现分别聚合、分别遵守合并
215		// 距离限制；已接受观测必然属于某次出现。
216		affected := replay.observed(frames[anchorIdx-1:])
217		affectedKeys := make([]occurrenceKey, 0, len(affected))
218		for k := range affected {
219			affectedKeys = append(affectedKeys, k)
220		}
221		sort.Slice(affectedKeys, func(i, j int) bool {
222			if affectedKeys[i].id != affectedKeys[j].id {
223				return affectedKeys[i].id < affectedKeys[j].id
224			}
225			return affectedKeys[i].num < affectedKeys[j].num
226		})
227	
228		// 逐“出现”登记固定旧贡献：旧文件第 1 次出现的既有观测无法重放，
229		// 其贡献固定为文件中的聚合值（位置不随校正改变）；其余观测随帧序列
230		// 重放。同一路标的不同出现互不参与彼此的合并。
231		for _, k := range affectedKeys {
232			occ := st.landmarks[k.id].appearances[k.num-1]
233			replay.seed(k.id, k.num, occ.legacyCount, occ.legacyMX, occ.legacyMY)
234		}
235		// 目标、原始观测与校正后位姿都有限，转换结果仍可能因数值过大
236		// 溢出为 NaN/无穷。与导入一致：数值异常优先于距离冲突，按
237		// non_finite 拒绝并指出该观测所在帧的实际时间、路标标识与
238		// 其所属的出现编号（不是锚点时间），无论该次出现此前是否已有
239		// 观测、记录仍有效还是已失效。
240		if rej := replay.replay(frames); rej != nil {
241			switch rej.reason {
242			case replayNonFinite:
243				return CorrectionRecord{}, &RejectError{
244					Kind:          RejectNonFinite,
245					Time:          rej.time,
246					HasTime:       true,
247					Landmark:      rej.id,
248					HasLandmark:   true,
249					Occurrence:    rej.num,
250					HasOccurrence: true,
251				}
252			case replayConflict:
253				return CorrectionRecord{}, &RejectError{
254					Kind:          RejectLandmarkConflict,
255					Time:          rej.time,
256					HasTime:       true,
257					Landmark:      rej.id,
258					HasLandmark:   true,
259					Occurrence:    rej.num,
260					HasOccurrence: true,
261				}
262			default:
263				// 已接受观测必然属于某个已登记出现；归属失败说明内存不变量
264				// 被破坏，不可能由本包产生，按损坏处理而非半提交。
265				return CorrectionRecord{}, ErrCorrupt
266			}
267		}
268		for _, k := range affectedKeys {
269			a := replay.agg(k.id, k.num)
270			occ := st.landmarks[k.id].appearances[k.num-1]
271			if !isFinite(a.x) || !isFinite(a.y) {
272				return CorrectionRecord{}, &RejectError{Kind: RejectNonFinite, Time: req.Anchor, HasTime: true}
273			}
274			if a.count != occ.count {
275				// 内存不变量被破坏不可能由本包写出，按损坏处理而非半提交。
276				return CorrectionRecord{}, ErrCorrupt
277			}
278		}
279	
280		// ---- 组装校正前后快照（记录不可变） ----
281		rec := &CorrectionRecord{
282			ID:        req.ID,
283			Anchor:    req.Anchor,
284			Target:    tgt,
285			EndTime:   st.trajectory[end].Time,
286			Poses:     make([]PoseChange, 0, end-anchorIdx+1),
287			Landmarks: make([]LandmarkChange, 0, len(affectedKeys)),
288		}
289		for j := anchorIdx; j <= end; j++ {
290			rec.Poses = append(rec.Poses, PoseChange{Before: st.trajectory[j], After: next[j]})
291		}
292		for _, k := range affectedKeys {
293			occ := st.landmarks[k.id].appearances[k.num-1]
294			a := replay.agg(k.id, k.num)
295			rec.Landmarks = append(rec.Landmarks, LandmarkChange{
296				ID:         k.id,
297				Occurrence: k.num,
298				Before:     Landmark{ID: k.id, X: occ.x, Y: occ.y, Count: occ.count},
299				After:      Landmark{ID: k.id, X: a.x, Y: a.y, Count: a.count},
300			})
301		}
302	
303		// ---- 全部校验通过：暂存提交并落盘；落盘失败精确回滚 ----
304		oldTraj := append([]Pose(nil), st.trajectory...)
305		type occSnapshot struct {
306			key  occurrenceKey
307			occ  *occurrenceState
308			x, y float64
309		}
310		oldOcc := make([]occSnapshot, 0, len(affectedKeys))
311		for _, k := range affectedKeys {
312			occ := st.landmarks[k.id].appearances[k.num-1]
313			oldOcc = append(oldOcc, occSnapshot{key: k, occ: occ, x: occ.x, y: occ.y})
314		}
315		oldCorrLen := len(st.corrections)
316	
317		st.trajectory = next
318		for _, s := range oldOcc {
319			a := replay.agg(s.key.id, s.key.num)
320			s.occ.x, s.occ.y = a.x, a.y
321		}
322		st.corrections = append(st.corrections, rec)
323		st.corrIndex[req.ID] = canonicalCorrectionHash(req.Anchor, tgt)
324	
325		if err := m.saveReplace(); err != nil {
326			st.trajectory = oldTraj
327			for _, s := range oldOcc {
328				s.occ.x, s.occ.y = s.x, s.y
329			}
330			st.corrections = st.corrections[:oldCorrLen]
331			delete(st.corrIndex, req.ID)
332			return CorrectionRecord{}, err
333		}
334		return cloneRecord(rec), nil
335	}
336	
337	// Corrections 返回按提交次序排列的成功校正记录副本。记录一经生成永不
338	// 被后续校正改写；后续校正只是以当时最新状态为起点生成新记录。
339	func (m *Map) Corrections() ([]CorrectionRecord, error) {
340		m.mu.Lock()
341		defer m.mu.Unlock()
342		if m.closed {
343			return nil, ErrClosed
344		}
345		out := make([]CorrectionRecord, 0, len(m.state.corrections))
346		for _, rec := range m.state.corrections {
347			out = append(out, cloneRecord(rec))
348		}
349		return out, nil
350	}
351	
352	func (st *mapState) correctionRecordByID(id string) *CorrectionRecord {
353		for _, rec := range st.corrections {
354			if rec.ID == id {
355				return rec
356			}
357		}
358		return nil
359	}
360	
361	func cloneRecord(rec *CorrectionRecord) CorrectionRecord {
362		if rec == nil {
363			return CorrectionRecord{}
364		}
365		cp := *rec
366		cp.Poses = append([]PoseChange(nil), rec.Poses...)
367		cp.Landmarks = append([]LandmarkChange(nil), rec.Landmarks...)
368		return cp
369	}
370

